BEGIN;
CREATE SCHEMA comm_test;
CREATE FUNCTION comm_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
CREATE FUNCTION comm_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
GRANT USAGE ON SCHEMA comm_test TO authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA comm_test TO authenticated;
INSERT INTO auth.users(id,email) SELECT ('25000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'comm-'||n||'@example.invalid' FROM generate_series(1,7)n;
INSERT INTO public.companies(id,nome,created_by) VALUES('15000000-0000-4000-8000-000000000001','Communication fixture','25000000-0000-4000-8000-000000000001'),('15000000-0000-4000-8000-000000000002','Other fixture','25000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) SELECT '15000000-0000-4000-8000-000000000001',('25000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'auditor',(ARRAY['admin_empresa','analista_transporte','supervisor','operador_logistico','motorista','cliente','admin_geral'])[n],'25000000-0000-4000-8000-000000000001' FROM generate_series(1,7)n;
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual) VALUES('35000000-0000-4000-8000-000000000001','15000000-0000-4000-8000-000000000001','COMM001','caminhao','Model fixture',1000);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,telefone,email,created_by) VALUES('45000000-0000-4000-8000-000000000001','15000000-0000-4000-8000-000000000001','Oficina fixture','11987654321','fixture@example.invalid','25000000-0000-4000-8000-000000000001');
INSERT INTO public.maintenance_orders(id,company_id,vehicle_id,partner_id,created_by,status,data_abertura,descricao_problema,km_abertura) VALUES('55000000-0000-4000-8000-000000000001','15000000-0000-4000-8000-000000000001','35000000-0000-4000-8000-000000000001','45000000-0000-4000-8000-000000000001','25000000-0000-4000-8000-000000000001','em_execucao',now()-interval '48 hours','Communication fixture',1000);
CREATE FUNCTION comm_test.act(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$ SELECT public.maintenance_communication_command('15000000-0000-4000-8000-000000000001',action,jsonb_build_object('order_id','55000000-0000-4000-8000-000000000001')||payload); $$;
GRANT EXECUTE ON FUNCTION comm_test.act(text,jsonb) TO authenticated;
SELECT comm_test.assert((SELECT count(*)=5 FROM public.maintenance_message_templates WHERE company_id='15000000-0000-4000-8000-000000000001'),'five initial templates');
SELECT comm_test.assert((SELECT count(*)=1 FROM public.maintenance_settings WHERE company_id='15000000-0000-4000-8000-000000000001'),'company default settings');
SELECT maintenance_private.process_communication_reminders();SELECT maintenance_private.process_communication_reminders();
SELECT comm_test.assert((SELECT count(*)=1 AND max(reminder_count)=1 FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001' AND resolved_at IS NULL),'no duplicate reminders on repeated execution');
SET LOCAL ROLE authenticated;SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000001',true);
SELECT comm_test.assert(comm_test.act('notifications')->>'unread'='1','owner notified');
SELECT comm_test.assert(comm_test.act('overview','{"hours":24}')->>'count'='1','no-contact overview');
SELECT set_config('comm_test.msg',(comm_test.act('prepare','{"canal":"whatsapp","conteudo":"Olá, Oficina! Atualização da OS?","request_id":"65000000-0000-4000-8000-000000000001"}')->>'id'),true);
SELECT comm_test.assert(comm_test.act('prepare','{"canal":"whatsapp","conteudo":"Olá, Oficina! Atualização da OS?","request_id":"65000000-0000-4000-8000-000000000001"}')->>'id'=current_setting('comm_test.msg'),'network retry is idempotent');
SELECT comm_test.assert((SELECT count(*)=1 FROM public.maintenance_messages WHERE company_id='15000000-0000-4000-8000-000000000001'),'one prepared message');
SELECT comm_test.denied($q$SELECT comm_test.act('prepare','{"canal":"whatsapp","conteudo":"Olá, Oficina! Atualização da OS?","assunto":"Outro assunto","request_id":"65000000-0000-4000-8000-000000000001"}')$q$);
SELECT comm_test.assert((SELECT situacao='preparada' AND efetivada_em IS NULL AND destinatario='5511987654321' FROM public.maintenance_messages WHERE company_id='15000000-0000-4000-8000-000000000001'),'prepare does not pretend delivery');
SELECT comm_test.assert(comm_test.act('notifications')->>'unread'='1','prepare does not clear reminder');
SELECT comm_test.act('record','{"canal":"interno","direcao":"enviada","conteudo":"Anotação interna não é contato com a oficina.","request_id":"65000000-0000-4000-8000-000000000004"}');
SELECT comm_test.assert(comm_test.act('notifications')->>'unread'='1','internal note does not clear reminder');
SELECT comm_test.act('notification_read',jsonb_build_object('id',(SELECT id FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001' AND resolved_at IS NULL)));
SELECT comm_test.assert(comm_test.act('notifications')->>'unread'='0','read marker');
RESET ROLE;SELECT maintenance_private.process_communication_reminders();
SELECT comm_test.assert((SELECT count(*)=1 AND max(reminder_count)=1 FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001'),'read marker does not create hourly duplicate');
UPDATE public.maintenance_notifications SET next_reminder_at=now()-interval '1 minute' WHERE company_id='15000000-0000-4000-8000-000000000001';SELECT maintenance_private.process_communication_reminders();
SELECT comm_test.assert((SELECT count(*)=1 AND max(reminder_count)=2 AND bool_and(read_at IS NULL) FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001'),'next interval reuses notification');
SET LOCAL ROLE authenticated;
SELECT comm_test.act('assign',jsonb_build_object('user_id','25000000-0000-4000-8000-000000000003','version',(SELECT version FROM public.maintenance_orders WHERE id='55000000-0000-4000-8000-000000000001')));
RESET ROLE;SELECT maintenance_private.process_communication_reminders();
SET LOCAL ROLE authenticated;SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000003',true);
SELECT comm_test.assert(comm_test.act('notifications')->>'unread'='1','assigned supervisor notified');
SELECT comm_test.denied($q$SELECT comm_test.act('confirm',jsonb_build_object('id',current_setting('comm_test.msg')))$q$);
SELECT comm_test.denied($q$SELECT comm_test.act('config')$q$);
SELECT comm_test.denied($q$SELECT comm_test.act('assign','{"user_id":"25000000-0000-4000-8000-000000000003","version":1}')$q$);
SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000004',true);
SELECT comm_test.assert((SELECT count(*)=0 FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001'),'operator cannot read someone else notification');
SELECT comm_test.act('prepare','{"canal":"email","conteudo":"Solicito orçamento da OS.","assunto":"Orçamento da OS","request_id":"65000000-0000-4000-8000-000000000002"}');
SELECT comm_test.denied($q$SELECT comm_test.act('template_save','{"nome":"Forbidden","categoria":"andamento","conteudo":"Olá"}')$q$);
SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000001',true);
SELECT comm_test.act('confirm',jsonb_build_object('id',current_setting('comm_test.msg')));
SELECT comm_test.act('confirm',jsonb_build_object('id',current_setting('comm_test.msg')));
SELECT comm_test.assert((SELECT situacao='confirmada' AND efetivada_em IS NOT NULL FROM public.maintenance_messages WHERE company_id='15000000-0000-4000-8000-000000000001' AND id=current_setting('comm_test.msg')::uuid),'manual confirmation recorded');
SELECT comm_test.assert((SELECT count(*)=0 FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001' AND resolved_at IS NULL),'confirmed contact resolves reminders');
SELECT comm_test.assert((SELECT count(*)=4 FROM public.maintenance_order_timeline WHERE company_id='15000000-0000-4000-8000-000000000001' AND tipo_evento='mensagem'),'retry confirmation does not duplicate timeline');
RESET ROLE;UPDATE public.maintenance_messages SET efetivada_em=now()-interval '25 hours' WHERE id=current_setting('comm_test.msg')::uuid;
SET LOCAL ROLE authenticated;
SELECT comm_test.assert(comm_test.act('overview','{"hours":24}')->>'count'='1','unanswered confirmed message appears after threshold');
SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000003',true);
SELECT comm_test.act('record','{"canal":"whatsapp","direcao":"recebida","conteudo":"Oficina confirmou conclusão amanhã.","request_id":"65000000-0000-4000-8000-000000000003"}');
SELECT comm_test.assert(comm_test.act('overview','{"hours":24}')->>'count'='0','response removes waiting overview');
SELECT comm_test.assert((SELECT count(*)>=4 FROM public.maintenance_vehicle_events WHERE company_id='15000000-0000-4000-8000-000000000001' AND kind='mensagem'),'messages in permanent vehicle dossier');
SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000002',true);
SELECT comm_test.act('template_save','{"nome":"Analyst template","categoria":"andamento","conteudo":"Olá, {nome_parceiro}! OS {numero_os}: {placa}, {modelo}, {previsao_entrega}.","ativo":true}');
SELECT comm_test.denied($q$SELECT comm_test.act('template_save','{"nome":"Invalid variables","categoria":"andamento","conteudo":"Olá {senha}"}')$q$);
SELECT comm_test.act('settings_save',jsonb_build_object('version',(SELECT version FROM public.maintenance_settings WHERE company_id='15000000-0000-4000-8000-000000000001'),'intervalo_cobranca_horas',12,'cobranca_ativa',true,'cobranca_statuses',jsonb_build_array('em_execucao','aguardando_peca')));
SELECT comm_test.assert((SELECT limite_aprovacao_supervisor=5000 FROM public.maintenance_settings WHERE company_id='15000000-0000-4000-8000-000000000001'),'communication settings preserve budget approval limit');
SELECT comm_test.assert((SELECT count(*)>=2 FROM public.maintenance_communication_audit WHERE company_id='15000000-0000-4000-8000-000000000001'),'template and settings changes audited');
SELECT comm_test.denied($q$SELECT public.maintenance_communication_command('15000000-0000-4000-8000-000000000002','config','{}')$q$);
SELECT comm_test.denied($q$SELECT maintenance_private.process_communication_reminders()$q$);
SELECT comm_test.assert(NOT has_table_privilege('authenticated','public.maintenance_messages','INSERT'),'messages require checked RPC');
SELECT comm_test.assert(NOT has_table_privilege('authenticated','public.maintenance_settings','UPDATE'),'settings require checked RPC');
SELECT comm_test.assert(NOT has_function_privilege('anon','public.maintenance_communication_command(uuid,text,jsonb)','EXECUTE'),'anonymous RPC denied');
SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000005',true);SELECT comm_test.denied($q$SELECT comm_test.act('context')$q$);
SELECT set_config('request.jwt.claim.sub','25000000-0000-4000-8000-000000000006',true);SELECT comm_test.denied($q$SELECT comm_test.act('context')$q$);
RESET ROLE;SELECT maintenance_private.process_communication_reminders();SELECT comm_test.assert((SELECT count(*)=0 FROM public.maintenance_notifications WHERE company_id='15000000-0000-4000-8000-000000000001' AND resolved_at IS NULL),'fresh response prevents reminders');
ROLLBACK;
